import java.util.*;

class Solution {
    private List<List<Integer>> g;
    private int[] disc, low;
    private int timer = 0;
    private List<List<Integer>> res;

    public List<List<Integer>> criticalLinks(int n, int[][] links) {
        g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : links) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        disc = new int[n];
        low = new int[n];
        Arrays.fill(disc, -1);
        res = new ArrayList<>();
        dfs(0, -1);
        return res;
    }

    private void dfs(int v, int parent) {
        disc[v] = low[v] = timer++;
        for (int u : g.get(v)) {
            if (u == parent) continue;
            if (disc[u] == -1) {
                dfs(u, v);
                low[v] = Math.min(low[v], low[u]);
                if (low[u] > disc[v]) res.add(Arrays.asList(v, u)); // u's subtree can't get back above v
            } else {
                low[v] = Math.min(low[v], disc[u]); // back edge
            }
        }
    }
}

