class Solution:
    def criticalLinks(self, n: int, links: List[List[int]]) -> List[List[int]]:
        g = [[] for _ in range(n)]
        for i, (a, b) in enumerate(links): g[a].append((b, i)); g[b].append((a, i))
        disc = [-1] * n; low = [0] * n; t = 0; out = []
        for s in range(n):
            if disc[s] >= 0: continue
            disc[s] = low[s] = t; t += 1
            st = [(s, -1, 0)]
            while st:
                v, pe, k = st.pop()
                if k < len(g[v]):
                    st.append((v, pe, k + 1))
                    u, e = g[v][k]
                    if e == pe: continue
                    if disc[u] < 0:
                        disc[u] = low[u] = t; t += 1; st.append((u, e, 0))
                    else: low[v] = min(low[v], disc[u])
                elif pe >= 0:
                    a, b = links[pe]; p = a if b == v else b
                    low[p] = min(low[p], low[v])
                    if low[v] > disc[p]: out.append([p, v])
        return out

