function criticalLinks(n, links) {
  const g = Array.from({length: n}, () => []);
  links.forEach(([a, b], i) => { g[a].push([b, i]); g[b].push([a, i]); });
  const disc = new Array(n).fill(-1), low = new Array(n).fill(0), out = []; let t = 0;
  const dfs = (v, pe) => { disc[v] = low[v] = t++;
    for (const [u, e] of g[v]) { if (e === pe) continue;
      if (disc[u] < 0) { dfs(u, e); low[v] = Math.min(low[v], low[u]); if (low[u] > disc[v]) out.push([v, u]); }
      else low[v] = Math.min(low[v], disc[u]); } };
  for (let s = 0; s < n; s++) if (disc[s] < 0) dfs(s, -1);
  return out;
}
